CREATE DATABASE IF NOT EXISTS nba_db;
USE nba_db;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


DROP TABLE IF EXISTS TeamPlayoffsPerformance;
DROP TABLE IF EXISTS TeamRegularSeasonPerformance;
DROP TABLE IF EXISTS PlayerPlayoffsPerformance;
DROP TABLE IF EXISTS PlayerRegularSeasonPerformance;
DROP TABLE IF EXISTS PLAYERS;
DROP TABLE IF EXISTS TEAMS;

-- TEAMS (parent)
CREATE TABLE TEAMS (
    teamID INT PRIMARY KEY,
    teamName VARCHAR(100),
    teamAbbreviation VARCHAR(10),
    logoUrl VARCHAR(255),
    conference VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- PLAYERS (child of TEAMS)
CREATE TABLE PLAYERS (
    playerID INT PRIMARY KEY,
    playerName VARCHAR(100),
    teamID INT,
    position VARCHAR(20),
    headshotUrl VARCHAR(255),
    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Player Regular Season Stats (child of PLAYERS + TEAMS)
CREATE TABLE PlayerRegularSeasonPerformance (
    playerID INT,
    teamID INT,
    teamName VARCHAR(100),
    location ENUM('HOME','AWAY',"OVERALL"),
    GP_X INT,
    MIN_X FLOAT,
    FGM FLOAT,
    FGA FLOAT,
    FG_PCT FLOAT,
    FG3M FLOAT,
    FG3A FLOAT,
    FG3_PCT FLOAT,
    FTM FLOAT,
    FTA FLOAT,
    FT_PCT FLOAT,
    offensiveREB FLOAT,
    defensiveREB FLOAT,
    REB FLOAT,
    AST FLOAT,
    TOV FLOAT,
    steal FLOAT,
    PF FLOAT,
    PTS FLOAT,
    PLUS_MINUS FLOAT,
    efficiency FLOAT,

    PRIMARY KEY (playerID, teamID,location),
    FOREIGN KEY (playerID) REFERENCES PLAYERS(playerID),
    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Player Playoff Stats (child of PLAYERS + TEAMS)
CREATE TABLE PlayerPlayoffsPerformance (
    playerID INT,
    teamID INT,
    teamName VARCHAR(100),
    location ENUM('HOME','AWAY',"OVERALL"),
    GP_X INT,
    MIN_X FLOAT,
    FGM FLOAT,
    FGA FLOAT,
    FG_PCT FLOAT,
    FG3M FLOAT,
    FG3A FLOAT,
    FG3_PCT FLOAT,
    FTM FLOAT,
    FTA FLOAT,
    FT_PCT FLOAT,
    offensiveREB FLOAT,
    defensiveREB FLOAT,
    REB FLOAT,
    AST FLOAT,
    TOV FLOAT,
    steal FLOAT,
    PF FLOAT,
    PTS FLOAT,
    PLUS_MINUS FLOAT,
    efficiency FLOAT,

    PRIMARY KEY (playerID, teamID,location),
    FOREIGN KEY (playerID) REFERENCES PLAYERS(playerID),
    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Team Regular Season Performance (child of TEAMS)
CREATE TABLE TeamRegularSeasonPerformance (
    teamID INT PRIMARY KEY,
    winRank INT,
    defRatingRank INT,
    defRebRank INT,
    stealRank INT,
    blockRank INT,

    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Team Playoffs Performance (child of TEAMS)
CREATE TABLE TeamPlayoffsPerformance (
    teamID INT PRIMARY KEY,
    winRank INT,
    defRatingRank INT,
    defRebRank INT,
    stealRank INT,
    blockRank INT,

    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Team Arena Details (child of TEAMS)
CREATE TABLE TeamArenaDetails (
    arenaDetailID INT PRIMARY KEY AUTO_INCREMENT, 

    teamID INT NOT NULL,                         

    city VARCHAR(100),
    state VARCHAR(10),
    arena VARCHAR(100),
    capacity INT,
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6),
    us_time_zone VARCHAR(50),
    division VARCHAR(50),
    elevation_m INT,

    FOREIGN KEY (teamID) REFERENCES TEAMS(teamID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Team Fixtures (child of TeamArenaDetails)
CREATE TABLE TeamFixtures (
    matchID INT PRIMARY KEY AUTO_INCREMENT,  

    arenaDetailID INT NOT NULL,           
    
    matchNumber INT,
    roundNumber INT,
    matchDate DATETIME,
    homeTeam VARCHAR(100),
    awayTeam VARCHAR(100),
    result VARCHAR(20),

    FOREIGN KEY (arenaDetailID) REFERENCES TeamArenaDetails(arenaDetailID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



